INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES
('a02f9e30-dc9b-5c5e-b29f-c2a8020401e6', 'f76b6d21-0b81-5507-8b75-2615983cd6a5', 'tr', $h$Sayaçlı Gres Tabancası – 2306P$h$, $h$sayacli-gres-tabancasi-2306p$h$, NULL, $h$<div> <div><p><strong>Neden 2306P Sayaçlı Gres Tabancası ?</strong></p><p>Sayaçlı gres tabancası ve oval dişli bir ölçüm sistemini birleştirerek, ağırlık ölçen bir sayaç tasarladık. LCD ekrandan pompaladığınız gresin miktarını anında ve kesin olarak görürsünüz. Sayaç, her bir işlemden sonra sıfırlayabileceğiniz bir total ve sıfırlayamayacağınız bir ana total içerir. Küçük boyutu ve hafif yapısı sayesinde onu normal bir gres tabancası yerine pnömatik, elektrikli veya hidrolik gresleme ekipmanlarıyla birlikte kullanırsınız. Bu pompa, aşırı maliyetli ve hassas yağlama gerektiren işler için ideal bir çözümdür.</p></div> </div>$h$, NULL, $h$Sayaçlı Gres Tabancası – 2306P | HD Marine$h$, $h$Neden 2306P Sayaçlı Gres Tabancası ? Sayaçlı gres tabancası ve oval dişli bir ölçüm sistemini birleştirerek, ağırlık ölçen bir sayaç tasarladık. LCD…$h$, 'reviewed'),
('80cbff12-0511-5fb6-9073-ace253750e73', '9d6fba9f-6f4e-591d-8a2b-a155d74f4ba3', 'tr', $h$Gres Tabancası – 230565$h$, $h$gres-tabancasi-230565$h$, NULL, $h$<div> <div><p><strong>Neden 230565 Gres Tabancası ?</strong></p><p>Havalı gres pompaları için gres tabancasını, zorlu ortamlara dayanacak şekilde ürettik. Hava ile çalışan herhangi bir gres pompasıyla uyumlu olan bu üstün kaliteli tabanca, uzun ömürlü ve dayanıklı çelik konstrüksiyona sahiptir. Tetiğe tam bastığınızda sürekli akış sağlar. Ergonomik ve kaplamalı tetiği sayesinde rahat bir kullanım sunar ve bilya yuvası gres kirliliğine karşı yüksek tolerans gösterir. Kilit somunu ile kolayca üst ayarlama yaparsınız. Tabancayı spiral hortumla birlikte göndeririz.</p></div> </div>$h$, NULL, $h$Gres Tabancası – 230565 | HD Marine$h$, $h$Neden 230565 Gres Tabancası ? Havalı gres pompaları için gres tabancasını, zorlu ortamlara dayanacak şekilde ürettik. Hava ile çalışan herhangi bir gres…$h$, 'reviewed'),
